{"code":"import pandas as pd, statsmodels.api as sm
x=pd.read_csv('data/explore.csv'); ex=['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm']
for v in ex:
 d=x.dropna(subset=[v,'species_richness']); X=pd.concat([d[[v]],pd.get_dummies(d.region,drop_first=True,dtype=float)],axis=1); m=sm.OLS(d.species_richness,sm.add_constant(X)).fit()
 print(v,round(m.params[v],3),round(m.pvalues[v],6))"}
